package com.b5.shared;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.util.*;
public abstract class BrandActivity extends Activity {
 public static final int BG=Color.rgb(8,9,11),CARD=Color.rgb(21,22,26),GOLD=Color.rgb(234,199,115),WHITE=Color.rgb(248,245,237),MUTED=Color.rgb(156,157,164),GREEN=Color.rgb(105,222,166);
 protected LinearLayout body; public final Handler ui=new Handler(Looper.getMainLooper());protected boolean alive=true;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);splash();}
 protected abstract void begin();
 void splash(){LinearLayout box=new LinearLayout(this);box.setGravity(Gravity.CENTER);box.setOrientation(LinearLayout.VERTICAL);box.setBackgroundColor(BG);Logo logo=new Logo(this);box.addView(logo,new LinearLayout.LayoutParams(dp(190),dp(190)));TextView a=text("B5 STUDIOS",24,GOLD);a.setLetterSpacing(.28f);box.addView(a);TextView b=text("Developed by B5",13,MUTED);box.addView(b);setContentView(box);logo.setScaleX(.7f);logo.setScaleY(.7f);logo.setAlpha(.2f);logo.animate().scaleX(1).scaleY(1).alpha(1).setDuration(2100).start();ui.postDelayed(()->{if(alive)begin();},2500);}
 public int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 public TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(size);t.setPadding(0,dp(7),0,dp(7));return t;}
 public GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));d.setStroke(dp(1),Color.rgb(56,51,39));return d;}
 public void page(String title,String subtitle){ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.setOnApplyWindowInsetsListener((v,i)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});sc.setBackgroundColor(BG);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(22),dp(22),dp(22),dp(32));sc.addView(body);LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);Logo l=new Logo(this);h.addView(l,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView studio=text("  B5 STUDIOS   /   USA",12,GOLD);studio.setLetterSpacing(.15f);h.addView(studio);body.addView(h);body.addView(text(title,32,WHITE));if(!subtitle.isEmpty())body.addView(text(subtitle,13,MUTED));setContentView(sc);}
 public LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(18),dp(12),dp(18),dp(12));c.setBackground(shape(CARD,20));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(12),0,dp(5));body.addView(c,p);return c;}
 public EditText input(LinearLayout parent,String hint,boolean password){EditText e=new EditText(this);e.setSingleLine(true);e.setTextColor(WHITE);e.setHintTextColor(MUTED);e.setHint(hint);e.setTextSize(15);e.setPadding(dp(14),dp(12),dp(14),dp(12));e.setBackground(shape(BG,12));e.setInputType(password?129:1);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(54));p.setMargins(0,dp(5),0,dp(5));parent.addView(e,p);return e;}
 public Button button(LinearLayout parent,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextColor(BG);b.setTextSize(15);b.setTypeface(null,android.graphics.Typeface.BOLD);GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(255,225,155),GOLD,Color.rgb(174,130,54)});g.setCornerRadius(dp(14));b.setBackground(g);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,dp(8),0,dp(5));parent.addView(b,p);b.setOnClickListener(v->action.run());return b;}
 public void note(LinearLayout p,String s){p.addView(text(s,13,MUTED));}public void footer(){TextView t=text("Powered by B5",12,GOLD);t.setGravity(Gravity.CENTER);body.addView(t);}
 public void message(String s){if(alive)new AlertDialog.Builder(this).setTitle("B5 STUDIOS").setMessage(s).setPositiveButton("OK",null).show();}
 public static class Logo extends View {Paint p=new Paint(3);public Logo(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight();c.save();c.scale(w/200f,h/200f);p.setShader(null);p.setColor(Color.rgb(234,199,115));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);p.setShadowLayer(18,0,0,0x887D5827);c.drawRoundRect(12,12,188,188,36,36,p);p.clearShadowLayer();p.setStyle(Paint.Style.FILL);p.setTypeface(Typeface.create("sans-serif-black",Typeface.BOLD));p.setTextSize(116);p.setColor(0xFF30200E);c.drawText("B",31,145,p);c.drawText("5",104,145,p);p.setShader(new LinearGradient(0,40,175,170,new int[]{0xFFFFF0BE,0xFFEBC970,0xFF20170B,0xFFF8D989,0xFF90632B},null,Shader.TileMode.CLAMP));p.setShadowLayer(9,0,0,0x88EAC773);c.drawText("B",28,141,p);c.drawText("5",101,141,p);p.clearShadowLayer();p.setShader(null);c.restore();}}
 @Override protected void onDestroy(){alive=false;ui.removeCallbacksAndMessages(null);super.onDestroy();}
}
